import net.runelite.client.events.RuneScapeProfileChanged;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;

@Slf4j
@PluginDescriptor(
	name = "TFA Splits Tracker",
	description = "Fractured Archive raid history, server room splits, total times and party members",
	tags = {"tfa", "fractured", "archive", "raid", "splits", "timer", "party"},
	enabledByDefault = true
)
public class TfaSplitsTrackerPlugin extends Plugin
{
	private static final String GROUP = "tfasplitstracker";
	@Inject private Client client;
	@Inject private ClientThread clientThread;
	@Inject private ClientToolbar toolbar;
	@Inject private ConfigManager configManager;
	@Inject private Gson gson;
	private TfaTracker tracker = new TfaTracker();
	private TfaSplitsTrackerPanel panel;
	private NavigationButton navigation;
	private volatile boolean running;
	private boolean storageHealthy = true;
	private boolean liveAvailable;

	@Override
	protected void startUp()
	{
		running = true;
		panel = new TfaSplitsTrackerPanel(this::delete, this::undoDelete);
		navigation = NavigationButton.builder().tooltip("TFA Splits Tracker").icon(icon()).priority(7).panel(panel).build();
		toolbar.addNavigation(navigation);
		clientThread.invokeLater(() ->
		{
			if (running)
			{
				load();
				reconcile();
				publish();
			}
		});
	}

	@Override
	protected void shutDown()
	{
		running = false;
		toolbar.removeNavigation(navigation);
		panel.stop();
		// Every accepted timing and roster update has already been persisted.
	}

	@Subscribe
	public void onProfileChanged(ProfileChanged event)
	{
		clientThread.invokeLater(() ->
		{
			if (running)
			{
				load();
				reconcile();
				publish();
			}
		});
	}

	@Subscribe
	public void onRuneScapeProfileChanged(RuneScapeProfileChanged event)
	{
		onProfileChanged(new ProfileChanged());
	}

	@Subscribe
	public void onChatMessage(ChatMessage event)
	{
		if (running && configManager.getRSProfileKey() != null && event.getType() == ChatMessageType.GAMEMESSAGE)
		{
			// Reconcile older messages first, including when a callback was not delivered.
			reconcile();
			if (tracker.accept(event.getMessage(), event.getTimestamp() * 1000L))
			{
				captureParty();
				saveAndPublish();
			}
		}
	}

	@Subscribe
	public void onGameTick(GameTick event)
	{
		if (running)
		{
			reconcile();
			if (captureParty())
			{
				saveAndPublish();
			}
			if (liveAvailable != raidHudVisible())
			{
				publish();
			}
		}
	}

	@Subscribe
	public void onGameStateChanged(GameStateChanged event)
	{
		if (running)
		{
			publish();
		}
	}

	@Subscribe
	public void onVarClientStrChanged(VarClientStrChanged event)
	{
		if (running && event.getIndex() >= VarClientID.TFA_CLIENT_NAME0 && event.getIndex() <= VarClientID.TFA_CLIENT_NAME7)
		{
			// The game refreshes all eight slots in one script; wait for that refresh to finish.
			clientThread.invokeLater(() ->
			{
				if (running && captureParty())
				{
					saveAndPublish();
				}
			});
		}
	}

	private void reconcile()
	{
		if (configManager.getRSProfileKey() == null || client.getGameState() != GameState.LOGGED_IN || client.getMessages() == null)
		{
			return;
		}
		List<MessageNode> messages = new ArrayList<>();
		for (MessageNode node : client.getMessages())
		{
			if (node.getType() == ChatMessageType.GAMEMESSAGE && node.getTimestamp() * 1000L >= tracker.lastEvent)
			{
				messages.add(node);
			}
		}
		messages.sort(Comparator.comparingInt(MessageNode::getTimestamp).thenComparingInt(MessageNode::getId));
		boolean changed = false;
		for (MessageNode node : messages)
		{
			changed |= tracker.accept(node.getValue(), node.getTimestamp() * 1000L);
		}
		if (changed)
		{
			captureParty();
			saveAndPublish();
		}
	}

	private boolean captureParty()
	{
		if (tracker.current() == null || !raidHudVisible())
		{
			return false;
		}
		List<String> names = new ArrayList<>();
		for (int slot = VarClientID.TFA_CLIENT_NAME0; slot <= VarClientID.TFA_CLIENT_NAME7; slot++)
		{
			names.add(client.getVarcStrValue(slot));
		}
		return tracker.party(names);
	}

	private boolean raidHudVisible()
	{
		Widget hud = client.getWidget(InterfaceID.TfaHud.UNIVERSE);
		return client.getGameState() == GameState.LOGGED_IN && hud != null && !hud.isHidden();
	}

	private void load()
	{
		tracker = new TfaTracker();
		storageHealthy = true;
		try
		{
			String json = configManager.getRSProfileConfiguration(GROUP, "history");
			if (json != null)
			{
				TfaTracker saved = gson.fromJson(json, TfaTracker.class);
				if (saved != null)
				{
					tracker = saved;
				}
			}
		}
		catch (RuntimeException ex)
		{
			storageHealthy = false;
			log.warn("Unable to read TFA splits history; preserving the stored data", ex);
		}
	}

	private void saveAndPublish()
	{
		if (storageHealthy && configManager.getRSProfileKey() != null)
		{
			configManager.setRSProfileConfiguration(GROUP, "history", gson.toJson(tracker));
		}
		publish();
	}

	private void delete(String raidId, String room)
	{
		String profile = configManager.getRSProfileKey();
		clientThread.invokeLater(() ->
		{
			if (running && profile != null && profile.equals(configManager.getRSProfileKey()) && tracker.delete(raidId, room))
			{
				saveAndPublish();
			}
		});
	}

	private void undoDelete()
	{
		String profile = configManager.getRSProfileKey();
		clientThread.invokeLater(() ->
		{
			if (running && profile != null && profile.equals(configManager.getRSProfileKey()) && tracker.undoDelete())
			{
				saveAndPublish();
			}
		});
	}

	private void publish()
	{
		// Swing receives its own immutable-in-practice copy; the game thread owns the reducer.
		TfaTracker snapshot = gson.fromJson(gson.toJson(tracker), TfaTracker.class);
		TfaSplitsTrackerPanel target = panel;
		boolean healthy = storageHealthy;
		liveAvailable = raidHudVisible();
		boolean available = liveAvailable;
		SwingUtilities.invokeLater(() ->
		{
			if (running && panel == target)
			{
				target.update(snapshot, healthy, available);
			}
		});
	}

	static BufferedImage icon()
	{
		BufferedImage image = new BufferedImage(24, 24, BufferedImage.TYPE_INT_ARGB);
		Graphics2D g = image.createGraphics();
		g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
		g.setColor(new Color(99, 218, 204));
		g.setStroke(new BasicStroke(2));
		g.drawOval(4, 5, 16, 16);
		g.drawLine(12, 8, 12, 13);
		g.drawLine(12, 13, 16, 15);
		g.drawLine(9, 2, 15, 2);
		g.drawLine(12, 2, 12, 5);
		g.dispose();
		return image;
	}
}

package com.tfasplitstracker;

import java.util.ArrayList;
import java.util.Arrays;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Set;
import java.util.regex.Matcher;
import java.util.regex.Pattern;

/** Event reducer shared by live chat, chat-buffer recovery, and recorded-log tests. */
final class TfaTracker
{
	static final Set<String> ROOMS = new LinkedHashSet<>(Arrays.asList("Archive Guardian", "Bork",
		"Dagon'hai Trio", "Ezekiel", "Dreadnoth the Jellied", "Moia", "Xarth", "Ocellus"));
	private static final String TIME = "(\\d+:\\d{2}(?::\\d{2})?(?:\\.\\d{1,3})?)";
	private static final Pattern START = Pattern.compile("^Challenge started: (.+)\\.$");
	private static final Pattern SPLIT = Pattern.compile("^Challenge complete: (.+)\\. Duration: " + TIME + "\\. Total: " + TIME + ".*$");
	private static final Pattern TOTAL = Pattern.compile("^The Fractured Archive: Total completion time: " + TIME + ".*$");
	private static final Pattern READY = Pattern.compile("^\\d+/([1-8]) party members are now ready\\.$");
	final List<TfaRaid> raids = new ArrayList<>();
	// Persist the event journal as well as the records, so re-enabling cannot replay old starts.
	final Set<String> processed = new LinkedHashSet<>();
	long lastEvent;
	TfaRaid deleted;
	int deletedIndex;
	boolean suppressUntilNextRaid;

	boolean delete(String raidId, String room)
	{
		for (int i = 0; i < raids.size(); i++)
		{
			TfaRaid raid = raids.get(i);
			if (!raid.id.equals(raidId) || room != null && raid.active())
			{
				continue;
			}
			if (room != null && raid.splits.stream().noneMatch(s -> s.room.equals(room)))
			{
				return false;
			}
			if (raid.active())
			{
				suppressUntilNextRaid = true;
			}
			else
			{
				deleted = raid.copy();
				deletedIndex = i;
			}
			if (room == null)
			{
				raids.remove(i);
			}
			else
			{
				raid.splits.removeIf(s -> s.room.equals(room));
			}
			// Keep the event journal: retained chat must not resurrect a deleted record.
			return true;
		}
		return false;
	}

	boolean undoDelete()
	{
		if (deleted == null)
		{
			return false;
		}
		raids.removeIf(r -> r.id.equals(deleted.id));
		// A newly started raid must remain first so current() can find it.
		int firstSaved = current() == null ? 0 : 1;
		raids.add(Math.min(raids.size(), Math.max(firstSaved, deletedIndex)), deleted);
		deleted = null;
		while (raids.size() > 200)
		{
			raids.remove(raids.size() - 1);
		}
		return true;
	}

	TfaRaid current()
	{
		return !raids.isEmpty() && raids.get(0).active() ? raids.get(0) : null;
	}

	boolean accept(String raw, long timestamp)
	{
		if (raw == null)
		{
			return false;
		}
		String message = raw.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
		Matcher start = START.matcher(message);
		Matcher split = SPLIT.matcher(message);
		Matcher total = TOTAL.matcher(message);
		Matcher ready = READY.matcher(message);
		boolean isStart = start.matches() && ROOMS.contains(start.group(1));
		boolean isSplit = split.matches() && ROOMS.contains(split.group(1));
		boolean isTotal = total.matches();
		boolean isReady = ready.matches() && current() != null;
		boolean failed = message.equals("You failed to survive the Fractured Archive.");
		boolean abandoned = message.equals("You abandon the raid and leave the Fractured Archive.");
		if (!isStart && !isSplit && !isTotal && !isReady && !failed && !abandoned)
		{
			return false;
		}
		String key = timestamp + ":" + message;
		if (processed.contains(key) || timestamp < lastEvent)
		{
			return false;
		}
		processed.add(key);
		while (processed.size() > 4096)
		{
			processed.remove(processed.iterator().next());
		}
		lastEvent = timestamp;
		if (suppressUntilNextRaid)
		{
			if (isStart && start.group(1).equals("Archive Guardian"))
			{
				suppressUntilNextRaid = false;
			}
			else
			{
				return true;
			}
		}
		if (isStart)
		{
			String room = start.group(1);
			TfaRaid raid = current();
			TfaRaid.Split previous = raid == null || raid.splits.isEmpty() ? null : raid.splits.get(raid.splits.size() - 1);
			if (previous != null && room.equals(previous.room) && previous.duration < 0 && previous.started == timestamp)
			{
				return true;
			}
			if (raid != null && room.equals("Archive Guardian"))
			{
				raid.status = "Interrupted";
				raid = null;
			}
			if (raid == null)
			{
				raid = create(timestamp);
			}
			TfaRaid.Split next = new TfaRaid.Split();
			next.room = room;
			next.started = timestamp;
			raid.splits.add(next);
			raid.updated = timestamp;
		}
		else if (isSplit)
		{
			String room = split.group(1);
			long duration = parseTime(split.group(2));
			long cumulative = parseTime(split.group(3));
			TfaRaid raid = current();
			if (raid != null && room.equals("Archive Guardian")
				&& raid.splits.stream().anyMatch(s -> s.room.equals(room) && s.duration >= 0))
			{
				// The next run's first completion also recovers a missed first-room start.
				raid.status = "Interrupted";
				raid = null;
			}
			if (raid == null)
			{
				// Ocellus and the overall message are separate signals for the same finish.
				TfaRaid last = raids.isEmpty() ? null : raids.get(0);
				if (last != null && "Completed".equals(last.status) && Math.abs(timestamp - last.updated) <= 2000)
				{
					raid = last;
				}
				else
				{
					raid = create(timestamp - cumulative);
				}
			}
			TfaRaid.Split result = raid.splits.stream().filter(s -> s.room.equals(room)).findFirst().orElse(null);
			if (result == null)
			{
				result = new TfaRaid.Split();
				result.room = room;
				result.started = timestamp - duration;
				raid.splits.add(result);
			}
			result.duration = duration;
			result.cumulative = cumulative;
			raid.total = cumulative;
			raid.updated = timestamp;
			if (room.equals("Ocellus"))
			{
				raid.status = "Completed";
			}
		}
		else if (isTotal)
		{
			TfaRaid raid = current();
			if (raid == null && !raids.isEmpty() && "Completed".equals(raids.get(0).status)
				&& Math.abs(timestamp - raids.get(0).updated) <= 2000)
			{
				raid = raids.get(0);
			}
			long duration = parseTime(total.group(1));
			if (raid == null)
			{
				raid = create(timestamp - duration);
			}
			raid.total = duration;
			raid.updated = timestamp;
			raid.status = "Completed";
		}
		else if (current() != null)
		{
			TfaRaid raid = current();
			if (isReady)
			{
				raid.teamSize = Integer.parseInt(ready.group(1));
			}
			else
			{
				raid.status = failed ? "Failed" : "Abandoned";
				raid.updated = timestamp;
			}
		}
		return true;
	}

	private TfaRaid create(long timestamp)
	{
		TfaRaid raid = new TfaRaid();
		raid.started = timestamp;
		raid.updated = timestamp;
		raids.add(0, raid);
		while (raids.size() > 200)
		{
			raids.remove(raids.size() - 1);
		}
		return raid;
	}

	boolean party(List<String> names)
	{
		TfaRaid raid = current();
		if (raid == null || names.isEmpty())
		{
			return false;
		}
		boolean changed = false;
		for (String raw : names)
		{
			String name = raw == null ? "" : raw.replaceAll("<[^>]*>", "").replace('\u00a0', ' ').trim();
			if (!name.isEmpty() && raid.members.stream().noneMatch(n -> n.equalsIgnoreCase(name)))
			{
				raid.members.add(name);
				changed = true;
			}
		}
		return changed;
	}

	static long parseTime(String value)
	{
		String[] parts = value.split(":");
		long seconds = 0;
		for (int i = 0; i < parts.length - 1; i++)
		{
			seconds = (seconds + Long.parseLong(parts[i])) * 60;
		}
		return seconds * 1000 + new java.math.BigDecimal(parts[parts.length - 1]).movePointRight(3).longValueExact();
	}
}

